        let total = 0;
        if (include) {
            for (let i = 0; i < edges.length; i++) {
                let [u, v, wt] = edges[i];
                if ((u === a && v === b) || (b === a && u === v)) {
                    let val = obj.union(a, b);
                    total += wt;
                    break;
